css:
@property --dgm-pulse-st { syntax: "<number>"; inherits: true; initial-value: 0; }
.dgm-pulse {
  --dgm-pulse-bg: oklch(0.975 0.009 80);
  --dgm-pulse-ink: oklch(0.25 0.025 45);
  --dgm-pulse-accent: oklch(0.62 0.19 33);
  --dgm-pulse-s1: var(--dgm-pulse-accent);
  --dgm-pulse-s2: oklch(from var(--dgm-pulse-accent) calc(l + .15) calc(c * .66) calc(h + 45));
  --dgm-pulse-s3: oklch(from var(--dgm-pulse-accent) calc(l - .12) calc(c * .3) calc(h + 195));
  --dgm-pulse-panel: color-mix(in oklch, var(--dgm-pulse-bg), white 72%);
  --dgm-pulse-line: color-mix(in oklch, var(--dgm-pulse-ink) 11%, transparent);
  --dgm-pulse-soft: color-mix(in oklch, var(--dgm-pulse-ink) 5%, transparent);
  --dgm-pulse-mute: color-mix(in oklch, var(--dgm-pulse-ink) 64%, var(--dgm-pulse-bg));
  --dgm-pulse-faint: color-mix(in oklch, var(--dgm-pulse-ink) 42%, var(--dgm-pulse-bg));
  --dgm-pulse-up: oklch(0.55 0.13 150);
  --dgm-pulse-down: oklch(0.56 0.18 28);
  --dgm-pulse-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dgm-pulse-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dgm-pulse-out: cubic-bezier(.16, 1, .3, 1);
  --dgm-pulse-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067, 1.087 24.1%, 1.083 26.4%, 1.032 33.6%, 1.006 38.5%, .996 45.8%, 1.001 61.5%, 1);
  width: 100%;
  height: var(--dgm-pulse-h, 680px);
  container-type: inline-size; container-name: dgm-pulse;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dgm-pulse-bg);
  color: var(--dgm-pulse-ink);
  font: 13px/1.45 var(--dgm-pulse-sans);
  color-scheme: light;
  accent-color: var(--dgm-pulse-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, dt, ul, li, table) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dgm-pulse-accent); outline-offset: 2px; border-radius: 6px; }
  & [hidden] { display: none !important; }
  & :where(.dgm-pulse__side, .dgm-pulse__main, .dgm-pulse__aside, .dgm-pulse__tablep, .dgm-pulse__calwrap) {
    scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dgm-pulse-ink) 22%, transparent) transparent;
  }
}
.dgm-pulse__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.dgm-pulse__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.dgm-pulse__shell { height: 100%; display: grid; grid-template-columns: 204px minmax(0, 1fr); grid-template-areas: "side main"; }

/* ---------- side ---------- */
.dgm-pulse__side {
  grid-area: side; display: flex; flex-direction: column; gap: 22px; padding: 18px 14px; min-height: 0; overflow: auto;
  border-right: 1px solid var(--dgm-pulse-line);
  background: color-mix(in oklch, var(--dgm-pulse-bg), var(--dgm-pulse-ink) 3%);
}
.dgm-pulse__brand { display: flex; align-items: center; gap: 10px; padding: 0 4px; }
.dgm-pulse__mark {
  display: grid; place-items: center; width: 36px; height: 36px; flex: none; border-radius: 11px;
  background: var(--dgm-pulse-ink); color: var(--dgm-pulse-bg);
  & svg { width: 21px; height: 21px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
}
.dgm-pulse__bt { display: grid; line-height: 1.2; min-width: 0;
  & b { font-size: 13.5px; font-weight: 750; letter-spacing: -.01em; }
  & small { font-size: 11px; color: var(--dgm-pulse-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.dgm-pulse__nav { display: grid; gap: 2px;
  & button {
    position: relative; display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 10px;
    font-weight: 600; color: var(--dgm-pulse-mute); transition: color .2s, background-color .2s;
    &:hover { color: var(--dgm-pulse-ink); background: var(--dgm-pulse-soft); }
    &[aria-current="page"] { color: var(--dgm-pulse-ink); background: var(--dgm-pulse-panel); box-shadow: 0 1px 0 var(--dgm-pulse-line), 0 0 0 1px var(--dgm-pulse-line); }
    &[aria-current="page"] .dgm-pulse__ic { color: var(--dgm-pulse-accent); }
  }
}
.dgm-pulse__meta { display: grid; gap: 10px; padding: 14px 6px 0; border-top: 1px dashed var(--dgm-pulse-line); margin-top: auto;
  & div { display: grid; gap: 1px; }
  & dt { font-size: 10px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--dgm-pulse-faint); }
  & dd { font-weight: 600; font-variant-numeric: tabular-nums; }
}
.dgm-pulse__def { padding: 0 6px; font-size: 11.5px; color: var(--dgm-pulse-faint); text-wrap: pretty; }

/* ---------- main ---------- */
.dgm-pulse__main {
  grid-area: main; min-width: 0; min-height: 0; display: grid; gap: 12px; padding: 16px 18px 14px;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  grid-template-areas: "head" "kpis" "view" "brush";
}
.dgm-pulse__head { grid-area: head; display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 10px 18px; }
.dgm-pulse__title { min-width: 0; flex: 1 1 300px; }
.dgm-pulse__eye { font-size: 10.5px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; color: var(--dgm-pulse-faint); }
.dgm-pulse__title h2 { margin-top: 4px; font-size: clamp(18px, 2.15cqi, 24px); font-weight: 760; letter-spacing: -.03em; line-height: 1.12; text-wrap: balance;
  & em { font-style: normal; color: var(--dgm-pulse-accent); }
}
.dgm-pulse__filters { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.dgm-pulse__chips { display: flex; gap: 6px; flex-wrap: wrap;
  & button {
    display: inline-flex; align-items: center; gap: 7px; padding: 5px 10px 5px 8px; border-radius: 999px; font-size: 12px; font-weight: 600;
    border: 1px solid var(--dgm-pulse-line); background: var(--dgm-pulse-panel); color: var(--dgm-pulse-faint);
    transition: color .2s, border-color .2s, background-color .2s, transform .35s var(--dgm-pulse-spring);
    & i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); opacity: .35; transform: scale(.75); transition: opacity .2s, transform .35s var(--dgm-pulse-spring); }
    &:hover { color: var(--dgm-pulse-ink); }
    &:active { transform: scale(.96); }
    &[aria-pressed="true"] { color: var(--dgm-pulse-ink); border-color: color-mix(in oklch, var(--c) 45%, var(--dgm-pulse-line)); background: color-mix(in oklch, var(--c) 9%, var(--dgm-pulse-panel)); }
    &[aria-pressed="true"] i { opacity: 1; transform: none; }
    &[aria-disabled="true"] { cursor: not-allowed; }
  }
}
.dgm-pulse__seg {
  position: relative; display: inline-flex; padding: 3px; border-radius: 10px; background: var(--dgm-pulse-soft); border: 1px solid var(--dgm-pulse-line);
  & button {
    position: relative; z-index: 1; padding: 4px 10px; border-radius: 7px; font-size: 12px; font-weight: 650; color: var(--dgm-pulse-mute); font-variant-numeric: tabular-nums;
    transition: color .2s;
    &:hover { color: var(--dgm-pulse-ink); }
    &[aria-checked="true"] { color: var(--dgm-pulse-ink); }
  }
  & .dgm-pulse__thumb { position: absolute; z-index: 0; top: 3px; bottom: 3px; left: 0; border-radius: 7px; background: var(--dgm-pulse-panel); box-shadow: 0 1px 2px color-mix(in oklch, var(--dgm-pulse-ink) 16%, transparent), 0 0 0 1px var(--dgm-pulse-line);
    transition: translate .5s var(--dgm-pulse-spring), width .5s var(--dgm-pulse-spring); }
  &:not(:has([aria-checked="true"])) .dgm-pulse__thumb { opacity: 0; }
}

/* KPIs */
.dgm-pulse__kpis { grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }
.dgm-pulse__kpi {
  position: relative; display: grid; gap: 2px; padding: 11px 14px 12px; border-radius: 14px; background: var(--dgm-pulse-panel); border: 1px solid var(--dgm-pulse-line); min-width: 0;
  animation: dgm-pulse-rise .7s var(--dgm-pulse-out) both; animation-delay: calc(var(--i) * 60ms + 120ms);
  & dt { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dgm-pulse-faint); }
  & dd { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; min-width: 0; }
  & .dgm-pulse__num { font-size: clamp(19px, 2.3cqi, 26px); font-weight: 760; letter-spacing: -.035em; font-variant-numeric: tabular-nums; line-height: 1.1; }
  & .dgm-pulse__sub { width: 100%; font-size: 11.5px; color: var(--dgm-pulse-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.dgm-pulse__delta { font-size: 11.5px; font-weight: 700; font-variant-numeric: tabular-nums; padding: 1px 6px; border-radius: 6px;
  &[data-s="up"] { color: var(--dgm-pulse-up); background: color-mix(in oklch, var(--dgm-pulse-up) 12%, transparent); }
  &[data-s="down"] { color: var(--dgm-pulse-down); background: color-mix(in oklch, var(--dgm-pulse-down) 12%, transparent); }
  &[data-s="na"] { color: var(--dgm-pulse-faint); background: var(--dgm-pulse-soft); }
}
.dgm-pulse__ring {
  position: absolute; right: 12px; top: 50%; translate: 0 -50%; width: 40px; height: 40px; border-radius: 50%;
  background: conic-gradient(var(--dgm-pulse-accent) calc(var(--dgm-pulse-st) * 1turn), color-mix(in oklch, var(--dgm-pulse-accent) 14%, transparent) 0);
  mask: radial-gradient(closest-side, transparent 68%, #000 70%);
  transition: --dgm-pulse-st .9s var(--dgm-pulse-out);
}

/* views */
.dgm-pulse__view { grid-area: view; min-height: 0; }
.dgm-pulse__view[data-view="pulse"] { display: grid; grid-template-columns: minmax(0, 1fr) 236px; gap: 12px; }
.dgm-pulse__panel { min-height: 0; border-radius: 16px; background: var(--dgm-pulse-panel); border: 1px solid var(--dgm-pulse-line); }
.dgm-pulse__chartp { position: relative; padding: 10px 6px 4px 4px; min-width: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.dgm-pulse__ch { display: flex; justify-content: space-between; gap: 10px; padding: 0 10px 0 14px; font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dgm-pulse-mute);
  & .dgm-pulse__hint { font-weight: 500; letter-spacing: 0; text-transform: none; font-size: 11px; color: var(--dgm-pulse-faint); }
}
.dgm-pulse__plot { position: relative; height: 100%; min-height: 200px; animation: dgm-pulse-wipe 1.15s var(--dgm-pulse-out) .15s both; }
.dgm-pulse__svg { display: block; width: 100%; height: 100%; overflow: visible; cursor: crosshair; outline-offset: -2px;
  & text { font: 10.5px var(--dgm-pulse-sans); fill: var(--dgm-pulse-faint); font-variant-numeric: tabular-nums; }
  & .g line { stroke: var(--dgm-pulse-line); }
  & .lbl { font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; fill: var(--dgm-pulse-mute); }
  & .ev { stroke: color-mix(in oklch, var(--dgm-pulse-ink) 38%, transparent); stroke-dasharray: 2 3; }
  & .ev.on { stroke: var(--dgm-pulse-ink); stroke-dasharray: none; }
  & .evband { fill: color-mix(in oklch, var(--dgm-pulse-ink) 5%, transparent); }
  & .xh { stroke: var(--dgm-pulse-ink); stroke-width: 1; opacity: .55; }
  & .dot { stroke: var(--dgm-pulse-panel); stroke-width: 2; }
  & .stl { fill: none; stroke: var(--dgm-pulse-ink); stroke-width: 1.75; stroke-linejoin: round; }
}
.dgm-pulse__flags { position: absolute; inset: 0; pointer-events: none; }
.dgm-pulse__flag {
  position: absolute; top: 0; translate: -50% 0; pointer-events: auto; display: inline-flex; align-items: center; gap: 4px;
  padding: 2px 7px 2px 5px; border-radius: 6px; font-size: 10.5px; font-weight: 700; white-space: nowrap;
  background: var(--dgm-pulse-panel); border: 1px solid var(--dgm-pulse-line); color: var(--dgm-pulse-mute);
  box-shadow: 0 1px 2px color-mix(in oklch, var(--dgm-pulse-ink) 10%, transparent);
  transition: color .2s, background-color .2s, border-color .2s, scale .3s var(--dgm-pulse-spring);
  & svg { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
  &:hover { color: var(--dgm-pulse-ink); scale: 1.05; }
  &[aria-pressed="true"] { color: var(--dgm-pulse-bg); background: var(--dgm-pulse-ink); border-color: var(--dgm-pulse-ink); }
}

/* aside */
.dgm-pulse__aside { padding: 14px 14px 12px; overflow: auto; display: grid; align-content: start; gap: 10px; }
.dgm-pulse__h3 { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--dgm-pulse-faint); display: flex; justify-content: space-between; align-items: baseline;
  & small { font-size: 10.5px; letter-spacing: 0; text-transform: none; font-weight: 500; }
  &:not(:first-child) { margin-top: 6px; }
}
.dgm-pulse__mix { display: grid; gap: 7px; }
.dgm-pulse__mixbar { display: flex; height: 10px; border-radius: 5px; overflow: hidden; gap: 2px;
  & span { background: var(--c); transition: flex-grow .6s var(--dgm-pulse-spring); min-width: 0; }
}
.dgm-pulse__mixrow { display: grid; grid-template-columns: 10px 1fr auto auto; gap: 8px; align-items: center; font-size: 12px;
  & i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
  & b { font-weight: 650; font-variant-numeric: tabular-nums; }
  & span:last-child { color: var(--dgm-pulse-faint); font-variant-numeric: tabular-nums; min-width: 38px; text-align: right; }
  &[data-off] { opacity: .4; }
}
.dgm-pulse__week { display: grid; grid-template-columns: repeat(7, 1fr); gap: 5px; align-items: end; height: 92px; }
.dgm-pulse__wd { display: grid; grid-template-rows: auto 1fr auto; height: 100%; gap: 3px; text-align: center; font-size: 10px; color: var(--dgm-pulse-faint); font-variant-numeric: tabular-nums;
  & .bar { align-self: end; width: 100%; height: calc(var(--v) * 100%); min-height: 3px; border-radius: 4px 4px 2px 2px; background: color-mix(in oklch, var(--dgm-pulse-ink) 16%, transparent); transform-origin: bottom; transition: height .6s var(--dgm-pulse-spring), background-color .3s; }
  &[data-top] .bar { background: var(--dgm-pulse-accent); }
  &[data-top] { color: var(--dgm-pulse-ink); font-weight: 700; }
}
.dgm-pulse__events { display: grid; gap: 4px;
  & button { width: 100%; display: grid; grid-template-columns: auto 1fr; gap: 1px 9px; padding: 7px 8px; border-radius: 9px; transition: background-color .2s;
    & svg { grid-row: span 2; width: 15px; height: 15px; margin-top: 1px; fill: none; stroke: var(--dgm-pulse-accent); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
    & b { font-size: 12px; font-weight: 650; }
    & span { font-size: 11px; color: var(--dgm-pulse-faint); }
    &:hover { background: var(--dgm-pulse-soft); }
    &[aria-pressed="true"] { background: color-mix(in oklch, var(--dgm-pulse-accent) 10%, transparent); }
  }
  & .dgm-pulse__none { font-size: 12px; color: var(--dgm-pulse-faint); padding: 4px 2px; text-wrap: pretty; }
}

/* table view */
.dgm-pulse__tablep { height: 100%; overflow: auto; padding: 6px 6px 12px; }
.dgm-pulse__table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dgm-pulse-panel); padding: 0; text-align: right; font-weight: 600; border-bottom: 1px solid var(--dgm-pulse-line); }
  & th:first-child, & td:first-child { text-align: left; }
  & th button { width: 100%; display: inline-flex; justify-content: inherit; align-items: center; gap: 4px; padding: 10px 12px; font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dgm-pulse-faint); justify-content: flex-end; }
  & th:first-child button { justify-content: flex-start; }
  & th button:hover { color: var(--dgm-pulse-ink); }
  & th[aria-sort] button { color: var(--dgm-pulse-ink); }
  & th button svg { width: 10px; height: 10px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; opacity: 0; transition: opacity .2s, rotate .3s var(--dgm-pulse-out); }
  & th[aria-sort] button svg { opacity: 1; }
  & th[aria-sort="ascending"] button svg { rotate: 180deg; }
  & th.sp { text-align: left; padding: 10px 12px; font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dgm-pulse-faint); }
  & td { padding: 11px 12px; text-align: right; border-bottom: 1px solid var(--dgm-pulse-line); white-space: nowrap; }
  & tbody tr { cursor: pointer; transition: background-color .2s; }
  & tbody tr:hover { background: var(--dgm-pulse-soft); }
  & tbody tr[aria-selected="true"] { background: color-mix(in oklch, var(--dgm-pulse-accent) 8%, transparent); box-shadow: inset 3px 0 0 var(--dgm-pulse-accent); }
  & tfoot td { font-weight: 750; border-bottom: 0; }
  & .pn { display: inline-flex; align-items: center; gap: 8px; font-weight: 650; }
  & .pn i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
  & .spark { width: 120px; height: 26px; display: block; }
  & .spark path { fill: none; stroke: var(--c); stroke-width: 1.6; stroke-linejoin: round; }
  & td.sp { text-align: left; }
}
.dgm-pulse__pdetail { margin: 14px 10px 0; padding: 14px 16px; border-radius: 12px; background: var(--dgm-pulse-soft); display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr); gap: 18px; align-items: center;
  & h4 { margin: 0 0 4px; font-size: 15px; font-weight: 750; letter-spacing: -.02em; }
  & p { color: var(--dgm-pulse-mute); text-wrap: pretty; }
  & .dgm-pulse__week { height: 84px; }
}

/* calendar view */
.dgm-pulse__calp { height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; gap: 10px; padding: 12px 14px; }
.dgm-pulse__calhead { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 8px 14px; }
.dgm-pulse__calsum { font-size: 12.5px; color: var(--dgm-pulse-mute); font-variant-numeric: tabular-nums; & b { color: var(--dgm-pulse-ink); } }
.dgm-pulse__calwrap { overflow: auto; min-height: 0; }
.dgm-pulse__cal { display: grid; grid-template-columns: 30px repeat(18, minmax(22px, 1fr)); grid-auto-rows: minmax(22px, 1fr); gap: 4px; min-width: 520px; height: 100%; min-height: 200px; }
.dgm-pulse__cl { font-size: 10px; color: var(--dgm-pulse-faint); align-self: center; font-variant-numeric: tabular-nums; white-space: nowrap; }
.dgm-pulse__cm { font-size: 10px; font-weight: 700; color: var(--dgm-pulse-faint); letter-spacing: .06em; text-transform: uppercase; align-self: end; white-space: nowrap; }
.dgm-pulse__cell {
  border-radius: 5px; background: color-mix(in oklch, var(--dgm-pulse-accent) calc(var(--v) * 100%), color-mix(in oklch, var(--dgm-pulse-ink) 5%, var(--dgm-pulse-panel)));
  cursor: pointer; transition: opacity .3s, scale .3s var(--dgm-pulse-spring), box-shadow .2s;
  animation: dgm-pulse-pop .5s var(--dgm-pulse-out) both; animation-delay: calc(var(--i) * 6ms);
  &[data-out] { opacity: .38; }
  &:hover { scale: 1.12; }
  &[aria-selected="true"] { box-shadow: 0 0 0 2px var(--dgm-pulse-ink); opacity: 1; }
  &[data-ev]::after { content: ""; display: block; width: 5px; height: 5px; margin: 3px; border-radius: 50%; background: var(--dgm-pulse-ink); }
}
.dgm-pulse__ramp { display: flex; align-items: center; gap: 8px; font-size: 11px; color: var(--dgm-pulse-faint); font-variant-numeric: tabular-nums;
  & i { width: 160px; height: 8px; border-radius: 4px; background: linear-gradient(90deg, color-mix(in oklch, var(--dgm-pulse-ink) 5%, var(--dgm-pulse-panel)), var(--dgm-pulse-accent)); }
}

/* brush */
.dgm-pulse__brush { grid-area: brush; }
.dgm-pulse__brushplot { position: relative; height: 58px; border-radius: 12px; background: var(--dgm-pulse-panel); border: 1px solid var(--dgm-pulse-line); }
.dgm-pulse__track { position: absolute; inset: 0 14px; cursor: crosshair; touch-action: none; }
.dgm-pulse__dim { position: absolute; top: 0; bottom: 0; pointer-events: none; background: color-mix(in oklch, var(--dgm-pulse-bg) 55%, transparent);
  &[data-dim="l"] { left: -14px; } &[data-dim="r"] { right: -14px; }
  &[data-dim="l"] { border-radius: 11px 0 0 11px; } &[data-dim="r"] { border-radius: 0 11px 11px 0; }
}
.dgm-pulse__bsvg { position: absolute; inset: 0; width: 100%; height: 100%;
  & .ar { fill: color-mix(in oklch, var(--dgm-pulse-ink) 10%, transparent); }
  & .ln { fill: none; stroke: color-mix(in oklch, var(--dgm-pulse-ink) 45%, transparent); stroke-width: 1.2; }
  & .tk { stroke: var(--dgm-pulse-accent); stroke-width: 1.5; }
