  DAYS.forEach((d, di) => { o += '<line x1="' + r1(X(d)) + '" x2="' + r1(X(d)) + '" y1="' + m.t + '" y2="' + (H - m.b) + '" style="opacity:.5"/><text x="' + r1(X(d)) + '" y="' + (H - 8) + '" text-anchor="middle"' + (di === S.hd ? ' style="fill:var(--dgm-retention-accent);font-weight:700"' : '') + '>D' + d + '</text>'; });
