    }
    if (pts.length > 1) o += '<path class="cv' + (isNew ? ' draw' : '') + '" pathLength="1" style="stroke:' + col + (ghost ? ';opacity:.45;stroke-dasharray:1 5' : '') + '" d="M' + pts.map((p) => r1(p[0]) + ',' + r1(p[1])).join('L') + '"/>';
    pts.forEach((p, k) => { const di = DAYS.indexOf(P[k][0]); const big = di === S.hd && (S.hc === c || S.hc < 0); o += '<circle class="pt" cx="' + r1(p[0]) + '" cy="' + r1(p[1]) + '" r="' + (big ? 5.5 : ghost ? 2.5 : 3.5) + '" style="fill:' + col + '"/>'; });
