  if (S.hd > -1) { const x = X(DAYS[S.hd]); o += '<line class="xh" x1="' + r1(x) + '" x2="' + r1(x) + '" y1="' + m.t + '" y2="' + (H - m.b) + '"/>'; }
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
