svg.addEventListener('pointerleave', () => { S.hd = -1; markHi(); drawCurves(true); hideTip(); });
svg.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') { e.preventDefault(); S.hd = clamp((S.hd < 0 ? -1 : S.hd) + (e.key === 'ArrowRight' ? 1 : -1), 0, DAYS.length - 1); S.hc = -1; markHi(); drawCurves(true); showTip(); }
  else if (e.key === 'Escape') { S.hd = -1; markHi(); drawCurves(true); hideTip(); }
});
svg.addEventListener('blur', () => { S.hd = -1; markHi(); drawCurves(true); hideTip(); });
function renderLegend() {
  const el = $('[data-legend]');
  el.innerHTML = S.sel.length ? S.sel.map((c, i) => { const d7 = valAt(c, 2); return '<li><button type="button" data-rm="' + c + '" style="--sc:' + PAL[i] + '" title="Remove ' + COH[c].label + ' from the chart"><i></i>' + COH[c].label + '<small>D7 ' + (d7 ? fP(d7.v) + (d7.proj ? '*' : '') : '–') + '</small><svg viewBox="0 0 12 12" aria-hidden="true"><path d="M3 3l6 6M9 3l-6 6"/></svg></button></li>'; }).join('')
    : '<li class="dgm-retention__lhint">No cohorts plotted. Select rows in the triangle.</li>';
}
$('[data-legend]').addEventListener('click', (e) => { const b = e.target.closest('[data-rm]'); if (b) { toggleCohort(+b.dataset.rm); const n = root.querySelector('[data-legend] button'); n && n.focus(); } });
$$('[data-sw]').forEach((b) => b.addEventListener('click', () => {
  const k = b.dataset.sw; S[k] = !S[k]; b.setAttribute('aria-checked', String(S[k])); drawCurves(true);
}));

/* ---------- sources view ---------- */
const splot = $('[data-splot]'), ssvg = $('[data-ssvg]');
function srcStats(s) {
  const L = s ? [s] : SRC;
  const out = { inst: COH.reduce((t, _, c) => t + inst(c, L), 0) };
  [0, 2, 4].forEach((di) => { out['d' + DAYS[di]] = pooled(di, L); });
  const pts = DAYS.map((d, di) => { const p = pooled(di, L); return p ? [d, p.v] : null; }).filter(Boolean);
  const f = fit(pts); out.d60 = f ? f(60) : null;
