}
let SG = null;
function drawSources(anim) {
  const W = splot.clientWidth, H = splot.clientHeight; if (!W || !H) return;
  const m = { l: 40, r: 14, t: 18, b: 30 }, iw = W - m.l - m.r, ih = H - m.t - m.b, YM = .55, Y = (v) => m.t + ih - v / YM * ih;
  const groups = [0, 2, 4], gw = iw / 3, bw = Math.min(34, gw / 4.6);
  let o = '<g class="g">';
  for (let v = 0; v <= .5001; v += .1) o += '<line x1="' + m.l + '" x2="' + (W - m.r) + '" y1="' + r1(Y(v)) + '" y2="' + r1(Y(v)) + '"/><text x="' + (m.l - 8) + '" y="' + r1(Y(v) + 3.5) + '" text-anchor="end">' + Math.round(v * 100) + '%</text>';
  o += '</g>';
  SG = [];
  groups.forEach((di, g) => {
    const cx = m.l + gw * g + gw / 2;
    o += '<text x="' + r1(cx) + '" y="' + (H - 9) + '" text-anchor="middle" class="lbl">D' + DAYS[di] + '</text>';
    SRC.forEach((s, k) => {
      const p = pooled(di, [s]), x = cx + (k - 1) * (bw + 6) - bw / 2, y = Y(p.v), h = m.t + ih - y;
      const dim = S.src !== 'all' && S.src !== s.k;
      o += '<g class="bar"' + (dim ? ' data-dim' : '') + '><rect x="' + r1(x) + '" y="' + r1(y) + '" width="' + r1(bw) + '" height="' + r1(h) + '" rx="4" style="fill:' + s.c + ';transform-origin:' + r1(x) + 'px ' + r1(m.t + ih) + 'px' + (anim && !RM.matches ? ';animation:dgm-retention-grow .7s ' + (g * 90 + k * 50) + 'ms cubic-bezier(.2,.9,.25,1) both' : '') + '"/>' +
        '<text x="' + r1(x + bw / 2) + '" y="' + r1(y - 5) + '" text-anchor="middle" style="fill:var(--dgm-retention-ink);font-weight:650">' + (p.v * 100).toFixed(1) + '</text></g>';
      SG.push({ x, w: bw, s, di, p });
    });
    const md = BM.p50(DAYS[di]);
    o += '<line x1="' + r1(cx - gw * .36) + '" x2="' + r1(cx + gw * .36) + '" y1="' + r1(Y(md)) + '" y2="' + r1(Y(md)) + '" style="stroke:var(--dgm-retention-warm);stroke-dasharray:3 3;stroke-width:1.5"/>';
  });
  ssvg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  ssvg.innerHTML = o;
}
ssvg.addEventListener('pointermove', (e) => {
  if (!SG) return;
  const r = ssvg.getBoundingClientRect(), x = e.clientX - r.left;
  const hit = SG.find((b) => x >= b.x - 3 && x <= b.x + b.w + 3);
  if (!hit) { hideTip(); return; }
  tip.innerHTML = '<b>' + hit.s.name + ' · D' + DAYS[hit.di] + '</b><div style="--sc:' + hit.s.c + '"><i></i><span>Retained</span><span>' + fP(hit.p.v) + '</span></div><div style="--sc:transparent"><i></i><span>Players</span><span>' + fI(hit.p.r) + ' / ' + fI(hit.p.n) + '</span></div>';
  const rr = root.getBoundingClientRect();
  let left = e.clientX - rr.left + 14; const w = tip.offsetWidth || 180; if (left + w > rr.width - 8) left -= w + 28;
  tip.style.translate = r1(left) + 'px ' + r1(e.clientY - rr.top - 20) + 'px'; tip.setAttribute('data-on', '');
});
ssvg.addEventListener('pointerleave', hideTip);
function renderSrcTable() {
  const all = srcStats(null);
  const head = '<thead><tr><th scope="col">Source</th><th scope="col">Installs</th><th scope="col">Share</th><th scope="col">D1</th><th scope="col">D7</th><th scope="col">D30</th><th scope="col" title="Power-law fit through the pooled curve">D60 fit</th><th scope="col" title="D7 relative to all sources, 100 = average">Quality</th></tr></thead>';
  const rows = SRC.map((s) => {
    const st = srcStats(s), q = Math.round(st.d7.v / all.d7.v * 100);
    return '<tr data-s="' + s.k + '" tabindex="' + (S.src === s.k || (S.src === 'all' && s.k === 'org') ? 0 : -1) + '" aria-selected="' + (S.src === s.k) + '" style="--sc:' + s.c + ';cursor:pointer' + (S.src !== 'all' && S.src !== s.k ? ';opacity:.5' : '') + '"><td><i></i>' + s.name + '</td><td>' + fI(st.inst) + '</td><td>' + fP(st.inst / all.inst) + '</td><td>' + fP(st.d1.v) + '</td><td>' + fP(st.d7.v) + '</td><td>' + fP(st.d30.v) + '</td><td>' + fP(st.d60) + '</td><td><span class="q" data-s="' + (q >= 100 ? 'up' : 'down') + '">' + q + '</span></td></tr>';
  }).join('');
  $('[data-stable]').innerHTML = head + '<tbody>' + rows + '</tbody><tfoot><tr><td>All sources</td><td>' + fI(all.inst) + '</td><td>100%</td><td>' + fP(all.d1.v) + '</td><td>' + fP(all.d7.v) + '</td><td>' + fP(all.d30.v) + '</td><td>' + fP(all.d60) + '</td><td>100</td></tr></tfoot>';
