$('[data-stable]').addEventListener('click', (e) => { const tr = e.target.closest('tr[data-s]'); if (tr) setSrc(S.src === tr.dataset.s ? 'all' : tr.dataset.s); });
$('[data-stable]').addEventListener('keydown', (e) => {
  const tr = e.target.closest('tr[data-s]'); if (!tr) return;
