/* ---------- first-session funnel ---------- */
const STEPS = [['Install', 1, 1], ['First launch', 1, 1], ['Finish tutorial', .68, .82], ['Plant first crop', .55, .68], ['First harvest', .38, .48], ['Meet a villager', .2, .24], ['Return next day', 0, 0]];
const LAUNCH = { pre: .955, post: .958 };
function funnel(era) {
  const from = era === 'pre' ? 0 : PATCH, to = era === 'pre' ? PATCH : NC;
