    li.querySelector('.gh').style.setProperty('--g', O[k].r.toFixed(4));
    li.querySelector('.pc').textContent = fP(s.r);
    li.querySelector('.rt').innerHTML = '<b' + (k ? ' data-s="' + (dd >= 0 ? 'up' : 'down') + '"' : '') + '>' + fI(s.n) + '</b>' + (k ? (k > 0 ? 'step ' + fP(conv) + ' · ' + (dd >= 0 ? '+' : '−') + Math.abs(dd).toFixed(1) + ' pts' : '') : 'cohort installs');
    li.toggleAttribute('data-worst', k === worst);
  });
