  $('[data-fttl]').textContent = COH[from].label + ' – ' + COH[to - 1].label + ' cohorts';
  $('[data-fnote]').innerHTML = '<i></i>Tick marks the ' + (S.era === 'pre' ? 'post' : 'pre') + '-patch rate. Biggest leak ' + (S.era === 'pre' ? 'before' : 'after') + ' 1.6: <b>' + F[worst].nm + '</b>, losing ' + fP(wd) + ' of the players who reached the step before it. Return next day is the D1 column of the triangle for these cohorts.';
