css:
.dgm-monetize {
  --dgm-monetize-bg: oklch(0.984 0.005 95);
  --dgm-monetize-ink: oklch(0.22 0.02 265);
  --dgm-monetize-accent: oklch(0.52 0.17 262);
  --dgm-monetize-gold: oklch(0.76 0.14 78);
  --dgm-monetize-panel: color-mix(in oklch, var(--dgm-monetize-bg), white 80%);
  --dgm-monetize-line: color-mix(in oklch, var(--dgm-monetize-ink) 11%, transparent);
  --dgm-monetize-soft: color-mix(in oklch, var(--dgm-monetize-ink) 4.5%, transparent);
  --dgm-monetize-mute: color-mix(in oklch, var(--dgm-monetize-ink) 64%, var(--dgm-monetize-bg));
  --dgm-monetize-faint: color-mix(in oklch, var(--dgm-monetize-ink) 44%, var(--dgm-monetize-bg));
  --dgm-monetize-tint: color-mix(in oklch, var(--dgm-monetize-accent) 9%, var(--dgm-monetize-panel));
  --dgm-monetize-up: oklch(0.55 0.13 155);
  --dgm-monetize-down: oklch(0.56 0.19 27);
  --dgm-monetize-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dgm-monetize-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dgm-monetize-out: cubic-bezier(.22, 1, .36, 1);
  --dgm-monetize-spring: linear(0, .01, .04 2.3%, .16 5%, .66 13.4%, .88 18%, 1.01 22.4%, 1.06 26%, 1.07 29.4%, 1.05 34%, 1.01 42%, .995 52%, 1);
  width: 100%;
  height: var(--dgm-monetize-h, 680px);
  container-type: inline-size; container-name: dgm-monetize;
  position: relative; isolation: isolate; overflow: hidden;
  display: grid; grid-template-rows: auto minmax(0, 1fr);
  border-radius: 18px; border: 1px solid var(--dgm-monetize-line);
  background: var(--dgm-monetize-bg);
  color: var(--dgm-monetize-ink);
  font: 13px/1.45 var(--dgm-monetize-sans);
  color-scheme: light;
  accent-color: var(--dgm-monetize-accent);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, dl, dd, dt, ul, li, table) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(button:disabled) { cursor: not-allowed; opacity: .45; }
  & :focus-visible { outline: 2px solid var(--dgm-monetize-accent); outline-offset: 2px; border-radius: 6px; }
  & [hidden] { display: none !important; }
  & :where(.dgm-monetize__view, .dgm-monetize__skus, .dgm-monetize__scen, .dgm-monetize__sku) { scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dgm-monetize-ink) 22%, transparent) transparent; }
}
.dgm-monetize__head { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 18px; padding: 14px 18px 12px; border-bottom: 1px solid var(--dgm-monetize-line); background: var(--dgm-monetize-panel); }
.dgm-monetize__id { display: flex; align-items: center; gap: 12px; min-width: 0; flex: 1 1 280px; }
.dgm-monetize__mark { display: grid; place-items: center; width: 36px; height: 36px; flex: none; border-radius: 10px; background: var(--dgm-monetize-accent); color: var(--dgm-monetize-panel);
  & svg { width: 21px; height: 21px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
}
.dgm-monetize__eye { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--dgm-monetize-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dgm-monetize__id h2 { font-size: clamp(17px, 1.9cqi, 21px); font-weight: 760; letter-spacing: -.025em; line-height: 1.2; text-wrap: balance;
  & em { font-style: normal; color: var(--dgm-monetize-accent); }
}
