/* scenario */
.dgm-monetize__scen { padding: 14px 15px; overflow: auto; display: grid; align-content: start; gap: 10px;
  & h3 { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--dgm-monetize-faint); }
  & .big { font-size: 22px; font-weight: 780; letter-spacing: -.03em; font-variant-numeric: tabular-nums; line-height: 1.15; }
  & .big[data-s="up"] { color: var(--dgm-monetize-up); } & .big[data-s="down"] { color: var(--dgm-monetize-down); }
