}
.dgm-monetize__quick { display: grid; gap: 6px;
  & button { display: grid; gap: 1px; padding: 8px 10px; border-radius: 9px; border: 1px solid var(--dgm-monetize-line); text-align: left; transition: border-color .2s, background-color .2s, translate .3s var(--dgm-monetize-spring);
    & b { font-size: 12px; font-weight: 650; } & span { font-size: 11px; color: var(--dgm-monetize-faint); }
    &:hover { border-color: color-mix(in oklch, var(--dgm-monetize-gold) 70%, var(--dgm-monetize-line)); background: color-mix(in oklch, var(--dgm-monetize-gold) 7%, transparent); translate: 2px 0; }
