.dgm-monetize__reset { justify-self: start; display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 8px; font-size: 12px; font-weight: 650; background: var(--dgm-monetize-ink); color: var(--dgm-monetize-panel);
