  & th { position: sticky; top: 0; z-index: 1; background: var(--dgm-monetize-panel); padding: 0; border-bottom: 1px solid var(--dgm-monetize-line); text-align: right; }
  & th:first-child, & td:first-child { text-align: left; }
  & th button { width: 100%; display: inline-flex; align-items: center; justify-content: flex-end; gap: 4px; padding: 11px 10px 9px; font-size: 10.5px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--dgm-monetize-faint); }
