.dgm-monetize__tip { position: absolute; z-index: 30; left: 0; top: 0; pointer-events: none; min-width: 170px; padding: 9px 11px; border-radius: 11px; background: var(--dgm-monetize-ink); color: var(--dgm-monetize-panel); font-size: 12px; font-variant-numeric: tabular-nums;
