  .dgm-monetize__view[data-view="store"] { grid-template-columns: minmax(0, 1fr); grid-auto-rows: max-content; }
  .dgm-monetize__skus { max-height: 380px; }
}
@container dgm-monetize (width < 440px) {
  .dgm-monetize__tree { grid-template-columns: minmax(0, 1fr); grid-template-areas: "book" "dau" "arpdau" "conv" "arppu" "tpp" "atv"; }
  .dgm-monetize__eye { display: none; }
