  --dgm-event-out: cubic-bezier(.16, 1, .3, 1);
  --dgm-event-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067, 1.087 24.1%, 1.083 26.4%, 1.032 33.6%, 1.006 38.5%, .996 45.8%, 1.001 61.5%, 1);
  --dgm-event-at: 70%;
