.dgm-event__feed { grid-area: feed; min-height: 0; overflow: auto; display: grid; align-content: start; gap: 14px; padding: 14px; border-radius: 16px; background: var(--dgm-event-panel); border: 1px solid var(--dgm-event-line); }
