.dgm-event__fun ol { display: grid; gap: 7px; margin-top: 9px; }
.dgm-event__fun li { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; column-gap: 8px; row-gap: 4px; align-items: baseline; font-size: 12px;
  animation: dgm-event-rise .6s var(--dgm-event-out) both; animation-delay: calc(var(--i) * 50ms + 200ms);
