/* ---------- scrubber ---------- */
.dgm-event__scrub { grid-area: scrub; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 12px; padding: 10px 12px; border-radius: 16px; background: var(--dgm-event-panel); border: 1px solid var(--dgm-event-line); }
