css:
.dgm-economy {
  --dgm-economy-bg: oklch(0.968 0.017 84);
  --dgm-economy-ink: oklch(0.29 0.035 55);
  --dgm-economy-src: oklch(0.55 0.085 192);
  --dgm-economy-sink: oklch(0.6 0.145 40);
  --dgm-economy-gold: oklch(0.76 0.135 80);
  --dgm-economy-gem: oklch(0.58 0.12 160);
  --dgm-economy-shard: oklch(0.62 0.09 250);
  --dgm-economy-panel: color-mix(in oklch, var(--dgm-economy-bg), white 55%);
  --dgm-economy-line: color-mix(in oklch, var(--dgm-economy-ink) 13%, transparent);
  --dgm-economy-soft: color-mix(in oklch, var(--dgm-economy-ink) 5.5%, transparent);
  --dgm-economy-mute: color-mix(in oklch, var(--dgm-economy-ink) 68%, var(--dgm-economy-bg));
  --dgm-economy-faint: color-mix(in oklch, var(--dgm-economy-ink) 46%, var(--dgm-economy-bg));
  --dgm-economy-up: oklch(0.52 0.12 150);
  --dgm-economy-down: oklch(0.55 0.17 30);
  --dgm-economy-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dgm-economy-serif: ui-serif, "New York", "Iowan Old Style", Georgia, serif;
  --dgm-economy-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dgm-economy-out: cubic-bezier(.16, 1, .3, 1);
  --dgm-economy-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067, 1.087 24.1%, 1.083 26.4%, 1.032 33.6%, 1.006 38.5%, .996 45.8%, 1.001 61.5%, 1);
  width: 100%;
  height: var(--dgm-economy-h, 680px);
  container-type: inline-size; container-name: dgm-economy;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background:
    repeating-linear-gradient(0deg, color-mix(in oklch, var(--dgm-economy-ink) 3%, transparent) 0 1px, transparent 1px 28px),
    var(--dgm-economy-bg);
  color: var(--dgm-economy-ink);
  font: 13px/1.45 var(--dgm-economy-sans);
  color-scheme: light;
  accent-color: var(--dgm-economy-sink);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, dt, ol, ul, li) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dgm-economy-sink); outline-offset: 2px; border-radius: 6px; }
  & [hidden] { display: none !important; }
  & :where(.dgm-economy__shell, .dgm-economy__side) { scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dgm-economy-ink) 22%, transparent) transparent; }
}
.dgm-economy__shell {
  height: 100%; display: grid; gap: 12px 14px; padding: 16px 18px;
  grid-template-columns: minmax(0, 1fr) 284px;
  grid-template-rows: auto auto minmax(0, 1fr) 168px;
  grid-template-areas: "head head" "kpis kpis" "flow side" "supply side";
}
.dgm-economy__head { grid-area: head; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px 18px; min-width: 0; }
.dgm-economy__id { display: flex; align-items: center; gap: 12px; min-width: 0; flex: 1 1 320px; }
.dgm-economy__mark { display: grid; place-items: center; width: 40px; height: 40px; flex: none; border-radius: 50%; color: var(--dgm-economy-bg);
  background: radial-gradient(circle at 35% 30%, color-mix(in oklch, var(--dgm-economy-gold), white 25%), var(--dgm-economy-gold) 45%, color-mix(in oklch, var(--dgm-economy-gold), var(--dgm-economy-ink) 35%));
  box-shadow: inset 0 0 0 2px color-mix(in oklch, var(--dgm-economy-ink) 18%, transparent);
  & svg { width: 21px; height: 21px; fill: none; stroke: var(--dgm-economy-ink); stroke-width: 1.6; stroke-linejoin: round; }
}
.dgm-economy__tt { min-width: 0; }
.dgm-economy__eye { font-size: 10.5px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; color: var(--dgm-economy-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dgm-economy__tt h2 { margin-top: 3px; font: 600 clamp(18px, 2.2cqi, 25px)/1.15 var(--dgm-economy-serif); letter-spacing: -.015em; text-wrap: balance;
  & em { font-style: italic; color: var(--dgm-economy-sink); }
}
.dgm-economy__ctl { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.dgm-economy__cur { display: inline-flex; gap: 2px; padding: 3px; border-radius: 11px; background: var(--dgm-economy-soft); border: 1px solid var(--dgm-economy-line);
  & button { display: inline-flex; align-items: center; gap: 6px; padding: 5px 10px; border-radius: 8px; font-size: 12px; font-weight: 650; color: var(--dgm-economy-mute); transition: background-color .2s, color .2s, box-shadow .2s;
    & i { width: 10px; height: 10px; border-radius: 50%; background: var(--c); box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--dgm-economy-ink) 25%, transparent); }
    &:hover { color: var(--dgm-economy-ink); }
    &[aria-selected="true"] { color: var(--dgm-economy-ink); background: var(--dgm-economy-panel); box-shadow: 0 1px 2px color-mix(in oklch, var(--dgm-economy-ink) 14%, transparent), 0 0 0 1px var(--dgm-economy-line); }
  }
}
.dgm-economy__weeks { display: inline-flex; border: 1px solid var(--dgm-economy-line); border-radius: 10px; overflow: hidden;
  & button { padding: 5px 9px; font: 600 11.5px var(--dgm-economy-mono); color: var(--dgm-economy-mute); font-variant-numeric: tabular-nums; transition: background-color .2s, color .2s;
    & + button { border-left: 1px solid var(--dgm-economy-line); }
    &:hover { background: var(--dgm-economy-soft); color: var(--dgm-economy-ink); }
    &[aria-checked="true"] { background: var(--dgm-economy-ink); color: var(--dgm-economy-bg); }
  }
}
.dgm-economy__switch { display: inline-flex; align-items: center; gap: 8px; padding: 5px 10px 5px 6px; border-radius: 10px; font-size: 12px; font-weight: 650; color: var(--dgm-economy-mute); border: 1px solid var(--dgm-economy-line); transition: background-color .2s, color .2s, border-color .2s;
  &:hover { color: var(--dgm-economy-ink); }
  &[aria-checked="true"] { color: var(--dgm-economy-ink); border-color: color-mix(in oklch, var(--dgm-economy-sink) 45%, transparent); background: color-mix(in oklch, var(--dgm-economy-sink) 8%, transparent); }
}
.dgm-economy__track { position: relative; width: 28px; height: 16px; border-radius: 999px; background: color-mix(in oklch, var(--dgm-economy-ink) 18%, transparent); transition: background-color .25s;
  & span { position: absolute; top: 2px; left: 2px; width: 12px; height: 12px; border-radius: 50%; background: white; box-shadow: 0 1px 2px color-mix(in oklch, var(--dgm-economy-ink) 35%, transparent); transition: translate .45s var(--dgm-economy-spring); }
}
.dgm-economy__switch[aria-checked="true"] .dgm-economy__track { background: var(--dgm-economy-sink);
  & span { translate: 12px 0; }
}

/* KPIs */
.dgm-economy__kpis { grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-block: 1px solid var(--dgm-economy-line); }
.dgm-economy__kpi { display: grid; gap: 1px; padding: 9px 16px 10px; min-width: 0;
  animation: dgm-economy-rise .7s var(--dgm-economy-out) both; animation-delay: calc(var(--i) * 60ms + 80ms);
  & + .dgm-economy__kpi { border-left: 1px solid var(--dgm-economy-line); }
  &:first-child { padding-left: 2px; }
  & dt { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dgm-economy-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; min-width: 0; }
  & .n { font: 600 clamp(20px, 2.5cqi, 28px)/1.1 var(--dgm-economy-serif); font-variant-numeric: lining-nums tabular-nums; letter-spacing: -.01em; }
  & .d { font-size: 11.5px; font-weight: 700; font-variant-numeric: tabular-nums; }
  & .d[data-s="up"] { color: var(--dgm-economy-up); } & .d[data-s="down"] { color: var(--dgm-economy-down); } & .d[data-s="na"] { color: var(--dgm-economy-mute); font-weight: 600; }
  & .s { width: 100%; font-size: 11.5px; color: var(--dgm-economy-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
}

/* sankey */
.dgm-economy__flow { grid-area: flow; position: relative; min-width: 0; min-height: 0; }
.dgm-economy__skw { position: absolute; inset: 0;
  & svg { display: block; width: 100%; height: 100%; overflow: visible; }
  & .ch { font: 700 10px var(--dgm-economy-sans); letter-spacing: .13em; text-transform: uppercase; fill: var(--dgm-economy-faint); }
  & .ch tspan { font-weight: 500; letter-spacing: .02em; text-transform: none; font-variant-numeric: tabular-nums; }
  & .lk { cursor: pointer; transition: opacity .25s; }
  & .lk[data-k="in"] { fill: color-mix(in oklch, var(--dgm-economy-src) 30%, transparent); }
  & .lk[data-k="out"] { fill: color-mix(in oklch, var(--dgm-economy-sink) 26%, transparent); }
  & .lk[data-k="keep"] { fill: color-mix(in oklch, var(--dgm-economy-gold) 42%, transparent); }
  & .lk:hover, & .lk[data-hot] { filter: saturate(1.4) brightness(.92); }
  & .lk[data-k="in"]:hover, & .lk[data-k="in"][data-hot] { fill: color-mix(in oklch, var(--dgm-economy-src) 52%, transparent); }
  & .lk[data-k="out"]:hover, & .lk[data-k="out"][data-hot] { fill: color-mix(in oklch, var(--dgm-economy-sink) 48%, transparent); }
  & .lk[data-k="keep"]:hover, & .lk[data-k="keep"][data-hot] { fill: color-mix(in oklch, var(--dgm-economy-gold) 66%, transparent); }
  & svg[data-focus] .lk:not([data-on]) { opacity: .12; }
  & svg[data-focus] .nd:not([data-on]) { opacity: .35; }
  & .nd { cursor: pointer; transition: opacity .25s; outline: none; }
  & .nd rect { rx: 3px; }
  & .nd[data-k="src"] rect { fill: var(--dgm-economy-src); }
  & .nd[data-k="stage"] rect { fill: var(--dgm-economy-ink); }
  & .nd[data-k="sink"] rect { fill: var(--dgm-economy-sink); }
  & .nd[data-k="keep"] rect { fill: var(--dgm-economy-gold); stroke: color-mix(in oklch, var(--dgm-economy-gold), var(--dgm-economy-ink) 35%); stroke-width: 1; }
  & .nd[data-sel] rect { stroke: var(--dgm-economy-ink); stroke-width: 2; }
  & .nd:focus-visible rect { stroke: var(--dgm-economy-sink); stroke-width: 3; }
  & .nd text { font: 600 11.5px var(--dgm-economy-sans); fill: var(--dgm-economy-ink); paint-order: stroke; stroke: var(--dgm-economy-bg); stroke-width: 4px; stroke-linejoin: round; pointer-events: none; }
  & .nd text tspan.v { font-weight: 500; fill: var(--dgm-economy-mute); font-variant-numeric: tabular-nums; }
  & .nd[data-k="keep"] text { font-weight: 750; }
}

/* supply */
.dgm-economy__supply { grid-area: supply; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 4px; min-width: 0; min-height: 0; padding-top: 8px; border-top: 1px solid var(--dgm-economy-line); }
.dgm-economy__sh { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; flex-wrap: wrap;
  & h3 { font-size: 10.5px; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; color: var(--dgm-economy-mute); }
}
.dgm-economy__lg { display: flex; gap: 12px; font-size: 11px; color: var(--dgm-economy-faint);
  & span { display: inline-flex; align-items: center; gap: 5px; }
  & i { width: 14px; height: 0; border-top: 2px solid var(--dgm-economy-ink); }
  & i.b { border-top: 2px dashed var(--dgm-economy-faint); }
  & i.c { border-top: 2px dashed var(--dgm-economy-sink); }
}
.dgm-economy__supw { position: relative; min-height: 0;
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; cursor: crosshair; }
  & svg:focus-visible { outline-offset: 2px; }
  & .gl { stroke: var(--dgm-economy-line); }
  & .yl, & .xl { font: 500 10px var(--dgm-economy-sans); fill: var(--dgm-economy-faint); font-variant-numeric: tabular-nums; }
  & .wk { fill: color-mix(in oklch, var(--dgm-economy-gold) 18%, transparent); transition: x .55s var(--dgm-economy-out); }
  & .bar { fill: color-mix(in oklch, var(--dgm-economy-gold) 70%, var(--dgm-economy-ink)); opacity: .55; }
  & .bar.neg { fill: var(--dgm-economy-sink); }
  & .sl { fill: none; stroke: var(--dgm-economy-ink); stroke-width: 2; stroke-linejoin: round; }
  & .pl { fill: none; stroke: var(--dgm-economy-faint); stroke-width: 1.6; stroke-dasharray: 4 4; }
  & .pp { fill: none; stroke: var(--dgm-economy-sink); stroke-width: 2; stroke-dasharray: 5 3; }
  & .pz { fill: color-mix(in oklch, var(--dgm-economy-ink) 3%, transparent); }
  & .hv { opacity: 0; transition: opacity .15s; } & .hv[data-on] { opacity: 1; }
  & .hv line { stroke: color-mix(in oklch, var(--dgm-economy-ink) 40%, transparent); }
  & .hv circle { fill: var(--dgm-economy-bg); stroke: var(--dgm-economy-ink); stroke-width: 2; }
}

/* side */
.dgm-economy__side { grid-area: side; min-height: 0; overflow: auto; display: grid; align-content: start; gap: 16px; padding: 14px 16px; border-radius: 14px; background: var(--dgm-economy-panel); border: 1px solid var(--dgm-economy-line);
  box-shadow: 0 1px 0 color-mix(in oklch, var(--dgm-economy-ink) 6%, transparent);
  & > * { animation: dgm-economy-rise .45s var(--dgm-economy-out) both; animation-delay: calc(var(--i, 0) * 45ms); }
  & h3 { font-size: 10.5px; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; color: var(--dgm-economy-mute); margin-bottom: 8px; }
  & .k { font-size: 10px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--kc, var(--dgm-economy-faint)); }
  & .nm { font: 600 19px/1.2 var(--dgm-economy-serif); letter-spacing: -.01em; margin-top: 2px; text-wrap: balance; }
  & .big { font: 600 26px/1.1 var(--dgm-economy-serif); font-variant-numeric: lining-nums tabular-nums; margin-top: 6px; }
  & .sub { font-size: 12px; color: var(--dgm-economy-mute); text-wrap: pretty; margin-top: 2px; }
  & .hint { font-size: 11.5px; color: var(--dgm-economy-faint); text-wrap: pretty; }
}
.dgm-economy__rows { display: grid; gap: 8px;
  & li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 3px 8px; font-size: 12px; align-items: baseline; }
  & span { color: var(--dgm-economy-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & b { font-weight: 650; font-variant-numeric: tabular-nums; }
  & small { color: var(--dgm-economy-faint); font-weight: 500; }
  & i { grid-column: 1 / -1; height: 5px; border-radius: 3px; background: var(--dgm-economy-soft); overflow: hidden; }
  & i::before { content: ""; display: block; height: 100%; width: calc(var(--w) * 100%); border-radius: inherit; background: var(--c, var(--dgm-economy-ink)); transform-origin: left; animation: dgm-economy-grow .7s var(--dgm-economy-out) both; animation-delay: calc(var(--i, 0) * 50ms + 120ms); }
}
.dgm-economy__trend { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; align-items: end; height: 92px;
  & button { display: grid; grid-template-rows: minmax(0, 1fr) auto; gap: 4px; height: 100%; padding: 0; border-radius: 6px; text-align: center;
    & span { align-self: end; justify-self: stretch; height: calc(var(--h) * 100%); min-height: 2px; border-radius: 4px 4px 2px 2px; background: color-mix(in oklch, var(--c) 45%, transparent); transform-origin: bottom; transition: background-color .2s; animation: dgm-economy-up .6s var(--dgm-economy-spring) both; animation-delay: calc(var(--i) * 50ms); }
    & small { font: 600 10.5px var(--dgm-economy-mono); color: var(--dgm-economy-faint); font-variant-numeric: tabular-nums; }
    &:hover span { background: color-mix(in oklch, var(--c) 70%, transparent); }
    &[aria-current="true"] span { background: var(--c); }
    &[aria-current="true"] small { color: var(--dgm-economy-ink); }
  }
}
.dgm-economy__mods { display: grid; gap: 6px;
  & li { display: grid; grid-template-columns: 8px minmax(0, 1fr); gap: 8px; font-size: 12px; color: var(--dgm-economy-mute); text-wrap: pretty; }
  & li::before { content: ""; width: 8px; height: 8px; margin-top: 5px; border-radius: 2px; background: var(--dgm-economy-sink); rotate: 45deg; }
  & b { color: var(--dgm-economy-ink); font-weight: 650; }
}
.dgm-economy__clear { justify-self: start; display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 9px; font-size: 12px; font-weight: 650; border: 1px solid var(--dgm-economy-line); transition: background-color .2s;
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  &:hover { background: var(--dgm-economy-soft); }
}

/* tooltip */
.dgm-economy__tip { position: absolute; z-index: 20; left: 0; top: 0; pointer-events: none; max-width: 250px; padding: 8px 11px; border-radius: 10px; font-size: 12px; line-height: 1.45; font-variant-numeric: tabular-nums;
  background: var(--dgm-economy-ink); color: var(--dgm-economy-bg); box-shadow: 0 12px 28px -12px color-mix(in oklch, var(--dgm-economy-ink) 70%, transparent);
  opacity: 0; scale: .96; transition: opacity .15s, scale .2s var(--dgm-economy-out);
  &[data-on] { opacity: 1; scale: 1; }
  & b { display: block; font-weight: 700; }
  & span { opacity: .78; }
}

@keyframes dgm-economy-rise { from { opacity: 0; translate: 0 6px; } }
@keyframes dgm-economy-grow { from { transform: scaleX(0); } }
@keyframes dgm-economy-up { from { transform: scaleY(0); } }

@container dgm-economy (width < 960px) {
  .dgm-economy__shell { grid-template-columns: minmax(0, 1fr) 236px; }
  .dgm-economy__kpi { padding-inline: 10px; }
}
@container dgm-economy (width < 760px) {
  .dgm-economy__shell { overflow: auto; padding: 14px 12px;
    grid-template-columns: minmax(0, 1fr); grid-template-rows: max-content max-content 380px max-content 170px;
    grid-template-areas: "head" "kpis" "flow" "side" "supply"; }
  .dgm-economy__kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dgm-economy__kpi:nth-child(3) { border-left: 0; padding-left: 2px; }
  .dgm-economy__kpi:nth-child(n + 3) { border-top: 1px solid var(--dgm-economy-line); }
  .dgm-economy__side { overflow: visible; }
}
@container dgm-economy (width < 460px) {
  .dgm-economy__shell { grid-template-rows: max-content max-content 400px max-content 160px; }
  .dgm-economy__eye { white-space: normal; }
  .dgm-economy__ctl { width: 100%; }
  .dgm-economy__skw .nd text { font-size: 10.5px; }
}

@media (prefers-reduced-motion: reduce) {
  .dgm-economy {
    & .dgm-economy__kpi, & .dgm-economy__side > *, & .dgm-economy__rows i::before, & .dgm-economy__trend span { animation: none; }
    & .dgm-economy__track span, & .dgm-economy__supw .wk { transition: none; }
    & .dgm-economy__tip { transition: opacity .1s; scale: 1; }
  }
}

