  const b = sup.getBoundingClientRect(), rb = root.getBoundingClientRect(); supTip(i, b.top - rb.top + 30);
});
sup.addEventListener('blur', hideTip);

/* ---------- sankey pointer + keys ---------- */
sk.addEventListener('pointerover', (e) => {
  const p = e.target.closest('.lk, .nd'); if (!p || !CURL) return;
  const rb = root.getBoundingClientRect(), C = CUR[S.c];
  if (p.classList.contains('lk')) {
    const l = CURL.Lk[p.dataset.id]; if (!l) return;
    p.setAttribute('data-hot', '');
    const a = nodeName(l.a), b = nodeName(l.b), av = valOf({ t: 'node', id: l.a }, D);
    showTip('<b>' + esc(a.name) + ' → ' + esc(b.name) + '</b>' + fV(l.v) + ' ' + C.low + ' <span>· ' + fP(l.v / av) + ' of ' + esc(a.short) + '</span>', e.clientX - rb.left, e.clientY - rb.top);
  } else {
    const n = CURL.N[p.dataset.id]; if (!n) return;
    const nm = nodeName(n.id);
    let x = fV(n.v) + ' ' + C.low;
    if (n.k === 'stage') { const st = D.stage.find((s) => 'g:' + s.id === n.id); x = 'Earned ' + fV(st.in) + ' · spent ' + fV(st.out) + '<br><span>Kept ' + fV(st.keep) + ' (' + fP(st.keep / st.in) + ')</span>'; }
    showTip('<b>' + esc(nm.name) + '</b>' + x, e.clientX - rb.left, e.clientY - rb.top);
  }
});
sk.addEventListener('pointermove', (e) => { if (tip.hasAttribute('data-on') && e.target.closest('.lk, .nd')) { const rb = root.getBoundingClientRect(); showTip(tip.innerHTML, e.clientX - rb.left, e.clientY - rb.top); } });
sk.addEventListener('pointerout', (e) => { const p = e.target.closest('.lk, .nd'); if (p && !p.contains(e.relatedTarget)) { p.removeAttribute('data-hot'); tip.removeAttribute('data-on'); } });
sk.addEventListener('click', (e) => {
  const p = e.target.closest('.lk, .nd'); if (!p) return;
  select(p.classList.contains('lk') ? 'link' : 'node', p.dataset.id);
});
sk.addEventListener('keydown', (e) => {
  const g = e.target.closest('.nd'); if (!g) return;
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select('node', g.dataset.id); return; }
  if (e.key === 'Escape') { if (S.sel) { S.sel = null; applySel(); renderSide(); } return; }
  const cols = { src: [], stage: [], sink: [] };
  $$('.dgm-economy__skw .nd').forEach((n) => { cols[n.dataset.k === 'keep' ? 'sink' : n.dataset.k].push(n); });
  const ck = g.dataset.k === 'keep' ? 'sink' : g.dataset.k, order = ['src', 'stage', 'sink'], col = cols[ck], i = col.indexOf(g);
  let nx = null;
  if (e.key === 'ArrowDown') nx = col[(i + 1) % col.length];
  else if (e.key === 'ArrowUp') nx = col[(i + col.length - 1) % col.length];
  else if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') { const c2 = cols[order[clamp(order.indexOf(ck) + (e.key === 'ArrowRight' ? 1 : -1), 0, 2)]]; nx = c2[Math.min(c2.length - 1, Math.round(i / Math.max(1, col.length - 1) * (c2.length - 1)))]; }
  if (nx) { e.preventDefault(); nx.focus(); }
});

/* ---------- controls ---------- */
function refresh(kind) {
  const prev = CURL;
  D = compute(S.c, S.w, S.scen);
  renderHead();
  if (kind === 'cur') { S.sel = null; rebuild(true); }
  else { const L = target(); if (L) morph(prev, L, 750); }
  renderSide(); drawSupply();
}
function setWeek(w) { if (w === S.w) return; S.w = w; refresh('week'); }
$('[data-weeks]').innerHTML = [1, 2, 3, 4].map((w) => '<button type="button" role="radio" data-w="' + w + '" title="' + WK[w] + ': ' + wRange(w) + '">' + WK[w] + '</button>').join('');
root.addEventListener('click', (e) => {
  const b = e.target.closest('button'); if (!b || !root.contains(b)) return;
  if (b.dataset.c && b.dataset.c !== S.c) { S.c = b.dataset.c; refresh('cur'); }
  else if (b.dataset.w) setWeek(+b.dataset.w);
  else if (b.dataset.tw) setWeek(+b.dataset.tw);
  else if (b.hasAttribute('data-scen')) { S.scen = !S.scen; refresh('scen'); }
  else if (b.hasAttribute('data-clear')) { S.sel = null; applySel(); renderSide(); const n = sk.querySelector('.nd'); if (n) n.focus({ preventScroll: true }); }
});
root.addEventListener('keydown', (e) => {
  const t = e.target;
  if (!t.closest) return;
  const grp = t.closest('[data-cur], [data-weeks]');
  if (grp && /^Arrow(Left|Right)$/.test(e.key)) {
    e.preventDefault();
    const bs = Array.from(grp.querySelectorAll('button')), i = bs.indexOf(t.closest('button')), n = bs[(i + (e.key === 'ArrowRight' ? 1 : bs.length - 1)) % bs.length];
    n.focus(); n.click();
  } else if (e.key === 'Escape' && S.sel && !t.closest('[data-sk]')) { S.sel = null; applySel(); renderSide(); }
});

/* ---------- lifecycle ---------- */
let rt = 0;
const ro = new ResizeObserver(() => {
  cancelAnimationFrame(rt);
  rt = requestAnimationFrame(() => {
    if (!root.isConnected) { ro.disconnect(); return; }
    if (skKey && skKey !== skw.clientWidth + 'x' + skw.clientHeight) {
      const was = CURL, L = target();
      if (L) { cancelAnimationFrame(raf); if (!was || L.narrow !== was.narrow || L.short !== was.short) { buildSk(L); applySel(); } drawSk(L); }
    }
    if (supKey && supKey !== supw.clientWidth + 'x' + supw.clientHeight) drawSupply();
  });
});
ro.observe(skw); ro.observe(supw);
renderHead(); renderSide();
requestAnimationFrame(() => {
  if (!root.isConnected) return;
  rebuild(true); drawSupply();
});

css:
.dgm-queue {
  --dgm-queue-bg: oklch(0.2 0.013 255);
  --dgm-queue-ink: oklch(0.93 0.01 250);
  --dgm-queue-ok: oklch(0.89 0.19 125);
  --dgm-queue-warn: oklch(0.81 0.15 72);
  --dgm-queue-bad: oklch(0.67 0.2 25);
  --dgm-queue-panel: color-mix(in oklch, var(--dgm-queue-bg), var(--dgm-queue-ink) 4%);
  --dgm-queue-deep: color-mix(in oklch, var(--dgm-queue-bg), black 22%);
  --dgm-queue-line: color-mix(in oklch, var(--dgm-queue-ink) 10%, transparent);
  --dgm-queue-soft: color-mix(in oklch, var(--dgm-queue-ink) 6%, transparent);
  --dgm-queue-mute: color-mix(in oklch, var(--dgm-queue-ink) 70%, var(--dgm-queue-bg));
  --dgm-queue-faint: color-mix(in oklch, var(--dgm-queue-ink) 46%, var(--dgm-queue-bg));
  --dgm-queue-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dgm-queue-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dgm-queue-out: cubic-bezier(.16, 1, .3, 1);
  --dgm-queue-snap: cubic-bezier(.3, 1.5, .5, 1);
  width: 100%;
  height: var(--dgm-queue-h, 680px);
  container-type: inline-size; container-name: dgm-queue;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 16px;
  background: var(--dgm-queue-bg);
  color: var(--dgm-queue-ink);
  font: 13px/1.45 var(--dgm-queue-sans);
  color-scheme: dark;
  accent-color: var(--dgm-queue-ok);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, dt, ol, ul, li) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(button:disabled) { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--dgm-queue-ok); outline-offset: 2px; border-radius: 6px; }
  & [hidden] { display: none !important; }
  & :where(.dgm-queue__shell, .dgm-queue__side, .dgm-queue__detail, .dgm-queue__hw) { scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dgm-queue-ink) 20%, transparent) transparent; }
}
.dgm-queue__shell {
  height: 100%; display: grid; gap: 10px 12px; padding: 0 14px 14px 0;
  grid-template-columns: 210px minmax(0, 1fr) 292px;
  grid-template-rows: auto auto minmax(0, 1fr) 190px;
  grid-template-areas: "side head head" "side kpis kpis" "side lanes detail" "side heat detail";
}
/* side */
.dgm-queue__side { grid-area: side; display: flex; flex-direction: column; gap: 10px; min-height: 0; overflow: auto; padding: 16px 12px 14px; background: var(--dgm-queue-deep); border-right: 1px solid var(--dgm-queue-line); }
.dgm-queue__brand { display: flex; align-items: center; gap: 10px; padding: 0 4px 8px; }
.dgm-queue__mark { display: grid; place-items: center; width: 34px; height: 34px; flex: none; border-radius: 10px; background: var(--dgm-queue-ok); color: var(--dgm-queue-deep);
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
}
.dgm-queue__bt { display: grid; line-height: 1.2; min-width: 0;
  & b { font-size: 13.5px; font-weight: 760; letter-spacing: -.01em; }
  & small { font-size: 11px; color: var(--dgm-queue-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.dgm-queue__lbl { padding: 2px 6px 0; font-size: 10px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--dgm-queue-faint); }
.dgm-queue__pls { display: grid; gap: 3px;
  & button { display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; align-items: center; gap: 0 9px; padding: 7px 8px; border-radius: 10px; color: var(--dgm-queue-mute); transition: background-color .2s, color .2s;
    &:hover { background: var(--dgm-queue-soft); color: var(--dgm-queue-ink); }
    &[aria-current="page"] { background: var(--dgm-queue-panel); color: var(--dgm-queue-ink); box-shadow: inset 0 0 0 1px var(--dgm-queue-line); }
  }
  & .ic { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; background: var(--dgm-queue-soft);
    & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  }
  & [aria-current="page"] .ic { color: var(--dgm-queue-ok); background: color-mix(in oklch, var(--dgm-queue-ok) 14%, transparent); }
  & .nm { font-size: 12.5px; font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .st { display: inline-flex; align-items: center; gap: 5px; font: 600 11px var(--dgm-queue-mono); font-variant-numeric: tabular-nums; color: var(--dgm-queue-faint); }
  & .st::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--c); box-shadow: 0 0 0 3px color-mix(in oklch, var(--c) 18%, transparent); }
}
.dgm-queue__legend { margin-top: auto; display: grid; gap: 8px; padding: 12px 4px 0; border-top: 1px dashed var(--dgm-queue-line);
  & ul { display: grid; gap: 4px; padding: 0 6px; }
  & li { display: flex; align-items: center; gap: 8px; font-size: 11.5px; color: var(--dgm-queue-mute); }
  & i { width: 7px; height: 7px; border-radius: 50%; background: var(--c); }
}
.dgm-queue__def { padding: 0 6px; font-size: 11px; color: var(--dgm-queue-faint); text-wrap: pretty; }

/* head */
.dgm-queue__head { grid-area: head; display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 8px 14px; padding-top: 14px; min-width: 0; }
.dgm-queue__title { min-width: 0; flex: 1 1 320px; }
.dgm-queue__eye { display: flex; align-items: center; gap: 8px; font: 600 10.5px var(--dgm-queue-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--dgm-queue-faint); }
.dgm-queue__dot { width: 7px; height: 7px; border-radius: 50%; background: var(--dgm-queue-ok); box-shadow: 0 0 0 0 color-mix(in oklch, var(--dgm-queue-ok) 60%, transparent); animation: dgm-queue-ping 1.8s var(--dgm-queue-out) infinite; }
.dgm-queue[data-paused] .dgm-queue__dot { background: var(--dgm-queue-faint); animation: none; }
.dgm-queue__title h2 { margin-top: 5px; font-size: clamp(17px, 2.05cqi, 23px); font-weight: 720; letter-spacing: -.025em; line-height: 1.15; text-wrap: balance;
  & em { font-style: normal; color: var(--dgm-queue-ok); }
  & em.bad { color: var(--dgm-queue-bad); }
}
.dgm-queue__live { display: inline-flex; align-items: center; gap: 7px; padding: 6px 12px 6px 9px; border-radius: 999px; font-size: 12px; font-weight: 650; border: 1px solid var(--dgm-queue-line); color: var(--dgm-queue-mute); transition: background-color .2s, color .2s, border-color .2s;
  & svg { width: 14px; height: 14px; fill: currentColor; }
  & .pl { display: none; }
  &:hover { color: var(--dgm-queue-ink); background: var(--dgm-queue-soft); }
  &[aria-pressed="true"] { color: var(--dgm-queue-ok); border-color: color-mix(in oklch, var(--dgm-queue-ok) 40%, transparent); }
  &[aria-pressed="true"] .pa { display: none; }
  &[aria-pressed="true"] .pl { display: block; }
}

/* kpis */
.dgm-queue__kpis { grid-area: kpis; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 1px; border-radius: 12px; overflow: hidden; background: var(--dgm-queue-line); border: 1px solid var(--dgm-queue-line); }
.dgm-queue__kpi { display: grid; gap: 0; padding: 9px 12px 10px; background: var(--dgm-queue-panel); min-width: 0;
  animation: dgm-queue-in .6s var(--dgm-queue-out) both; animation-delay: calc(var(--i) * 50ms + 80ms);
  & dt { font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dgm-queue-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { display: flex; align-items: baseline; gap: 6px; min-width: 0; }
  & .n { font: 650 clamp(18px, 2.2cqi, 24px)/1.2 var(--dgm-queue-mono); letter-spacing: -.03em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & .u { font-size: 11.5px; color: var(--dgm-queue-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  &[data-s="bad"] .n { color: var(--dgm-queue-bad); }
  &[data-s="warn"] .n { color: var(--dgm-queue-warn); }
  &[data-s="ok"] .n { color: var(--dgm-queue-ok); }
}

/* lanes */
.dgm-queue__lanes, .dgm-queue__heat { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 6px; min-width: 0; min-height: 0; padding: 10px 12px 10px; border-radius: 14px; background: var(--dgm-queue-panel); border: 1px solid var(--dgm-queue-line); }
.dgm-queue__lanes { grid-area: lanes; }
.dgm-queue__heat { grid-area: heat; }
.dgm-queue__lh { display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap;
  & h3 { font-size: 10.5px; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; color: var(--dgm-queue-mute);
    & b { font-weight: inherit; }
    & span { margin-left: 6px; font-weight: 500; letter-spacing: 0; text-transform: none; color: var(--dgm-queue-faint); } }
  & p { font-size: 11px; color: var(--dgm-queue-faint); }
}
.dgm-queue__cw { position: relative; min-height: 0;
  & canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; cursor: pointer; }
}
.dgm-queue__seg { display: inline-flex; padding: 2px; border-radius: 8px; background: var(--dgm-queue-deep); border: 1px solid var(--dgm-queue-line);
  & button { padding: 3px 8px; border-radius: 6px; font-size: 11px; font-weight: 650; color: var(--dgm-queue-faint); transition: background-color .2s, color .2s;
    &:hover { color: var(--dgm-queue-ink); }
    &[aria-checked="true"] { background: var(--dgm-queue-soft); color: var(--dgm-queue-ink); box-shadow: inset 0 0 0 1px var(--dgm-queue-line); }
  }
}
.dgm-queue__hw { position: relative; min-height: 0; overflow-x: auto; overflow-y: hidden;
  & svg { display: block; width: 100%; height: 100%; min-width: 420px; overflow: visible; }
  & svg:focus-visible { outline-offset: 0; }
  & .cl { cursor: pointer; rx: 2.5px; stroke: var(--dgm-queue-panel); stroke-width: 1.5; transition: opacity .2s; animation: dgm-queue-cell .5s var(--dgm-queue-out) both; animation-delay: calc(var(--i) * 6ms); }
  & .cl:hover { stroke: var(--dgm-queue-ink); }
  & .cl[data-sel] { stroke: var(--dgm-queue-ink); stroke-width: 2.5; }
  & .cl[data-kc] { stroke: var(--dgm-queue-ok); stroke-width: 2.5; }
  & .cl[data-cur] { stroke: color-mix(in oklch, var(--dgm-queue-ink) 70%, transparent); stroke-width: 2.5; stroke-dasharray: 2 2; }
  & svg[data-reg] .cl:not([data-row]) { opacity: .4; }
  & .rl, & .hl { font: 500 10px var(--dgm-queue-sans); fill: var(--dgm-queue-faint); font-variant-numeric: tabular-nums; }
  & .rl[data-on] { fill: var(--dgm-queue-ink); font-weight: 700; }
  & .nw { fill: var(--dgm-queue-ok); font: 700 9px var(--dgm-queue-mono); letter-spacing: .06em; }
}

/* detail */
.dgm-queue__detail { grid-area: detail; min-height: 0; overflow: auto; display: grid; align-content: start; gap: 12px; padding: 12px 14px; border-radius: 14px; background: var(--dgm-queue-panel); border: 1px solid var(--dgm-queue-line);
  & > * { animation: dgm-queue-in .45s var(--dgm-queue-out) both; animation-delay: calc(var(--i, 0) * 40ms); }
  & .k { font: 600 10px var(--dgm-queue-mono); letter-spacing: .12em; text-transform: uppercase; color: var(--dgm-queue-faint); }
  & .nm { margin-top: 2px; font-size: 18px; font-weight: 720; letter-spacing: -.02em; }
  & h4 { margin: 0 0 6px; font-size: 10px; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; color: var(--dgm-queue-mute); }
  & .note { font-size: 11.5px; color: var(--dgm-queue-faint); text-wrap: pretty; }
}
.dgm-queue__tiles { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px;
  & div { padding: 7px 8px; border-radius: 9px; background: var(--dgm-queue-deep); min-width: 0; }
  & dt { font-size: 9.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dgm-queue-faint); }
  & dd { font: 650 15px var(--dgm-queue-mono); font-variant-numeric: tabular-nums; white-space: nowrap; }
  & dd[data-s="bad"] { color: var(--dgm-queue-bad); } & dd[data-s="warn"] { color: var(--dgm-queue-warn); } & dd[data-s="ok"] { color: var(--dgm-queue-ok); }
}
.dgm-queue__hist, .dgm-queue__rule { display: block; width: 100%; height: 92px; overflow: visible;
  & .b { transform-origin: bottom; transform-box: fill-box; animation: dgm-queue-grow .55s var(--dgm-queue-snap) both; animation-delay: calc(var(--i) * 18ms); }
  & .ax { font: 500 9.5px var(--dgm-queue-sans); fill: var(--dgm-queue-faint); font-variant-numeric: tabular-nums; }
  & .slo { stroke: var(--dgm-queue-bad); stroke-dasharray: 3 3; }
  & .slot { font: 700 9px var(--dgm-queue-mono); fill: var(--dgm-queue-bad); }
  & .mk { stroke: var(--dgm-queue-ink); stroke-width: 1; }
  & .mkt { font: 700 9px var(--dgm-queue-mono); fill: var(--dgm-queue-ink); }
  & .st { fill: none; stroke: var(--dgm-queue-ok); stroke-width: 2; stroke-linejoin: round; }
  & .ar { fill: color-mix(in oklch, var(--dgm-queue-ok) 12%, transparent); }
  & .gl { stroke: var(--dgm-queue-line); }
}
.dgm-queue__hist { cursor: crosshair; }
.dgm-queue__acts { display: grid; gap: 6px; }
.dgm-queue__sw { display: flex; align-items: center; justify-content: space-between; gap: 10px; width: 100%; padding: 8px 10px; border-radius: 10px; background: var(--dgm-queue-deep); font-size: 12px; font-weight: 600; text-align: left;
  & small { display: block; font-weight: 500; font-size: 11px; color: var(--dgm-queue-faint); }
  & .tr { position: relative; flex: none; width: 30px; height: 17px; border-radius: 999px; background: color-mix(in oklch, var(--dgm-queue-ink) 20%, transparent); transition: background-color .25s; }
  & .tr::after { content: ""; position: absolute; top: 2px; left: 2px; width: 13px; height: 13px; border-radius: 50%; background: var(--dgm-queue-ink); transition: translate .35s var(--dgm-queue-snap); }
  &[aria-checked="true"] .tr { background: var(--dgm-queue-ok); }
  &[aria-checked="true"] .tr::after { translate: 13px 0; background: var(--dgm-queue-deep); }
}
.dgm-queue__btn { display: inline-flex; justify-content: center; align-items: center; gap: 7px; padding: 8px 10px; border-radius: 10px; font-size: 12px; font-weight: 650; border: 1px solid var(--dgm-queue-line); transition: background-color .2s, opacity .2s;
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  &:hover:not(:disabled) { background: var(--dgm-queue-soft); }
  &:disabled { opacity: .55; }
  &.ghost { justify-self: start; border-style: dashed; }
}

/* tooltip, toast */
.dgm-queue__tip { position: absolute; z-index: 20; left: 0; top: 0; pointer-events: none; max-width: 240px; padding: 8px 10px; border-radius: 10px; font-size: 12px; line-height: 1.5; font-variant-numeric: tabular-nums;
  background: color-mix(in oklch, var(--dgm-queue-bg), black 40%); border: 1px solid var(--dgm-queue-line); box-shadow: 0 14px 30px -14px black;
  opacity: 0; transition: opacity .12s;
  &[data-on] { opacity: 1; }
  & b { display: block; font-weight: 700; }
  & span { color: var(--dgm-queue-mute); }
}
