css:
.dgm-crash {
  --dgm-crash-bg: oklch(0.985 0.004 250);
  --dgm-crash-ink: oklch(0.24 0.02 262);
  --dgm-crash-accent: oklch(0.57 0.21 24);
  --dgm-crash-vela: oklch(0.55 0.14 255);
  --dgm-crash-corra: oklch(0.62 0.13 168);
  --dgm-crash-pyxis: oklch(0.72 0.15 68);
  --dgm-crash-panel: white;
  --dgm-crash-line: color-mix(in oklch, var(--dgm-crash-ink) 11%, transparent);
  --dgm-crash-soft: color-mix(in oklch, var(--dgm-crash-ink) 4.5%, transparent);
  --dgm-crash-mute: color-mix(in oklch, var(--dgm-crash-ink) 66%, var(--dgm-crash-bg));
  --dgm-crash-faint: color-mix(in oklch, var(--dgm-crash-ink) 44%, var(--dgm-crash-bg));
  --dgm-crash-good: oklch(0.55 0.13 150);
  --dgm-crash-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dgm-crash-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dgm-crash-out: cubic-bezier(.16, 1, .3, 1);
  --dgm-crash-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067, 1.087 24.1%, 1.083 26.4%, 1.032 33.6%, 1.006 38.5%, .996 45.8%, 1.001 61.5%, 1);
  width: 100%;
  height: var(--dgm-crash-h, 680px);
  container-type: inline-size; container-name: dgm-crash;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 14px;
  background: var(--dgm-crash-bg);
  color: var(--dgm-crash-ink);
  font: 13px/1.45 var(--dgm-crash-sans);
  color-scheme: light;
  accent-color: var(--dgm-crash-accent);
  -webkit-font-smoothing: antialiased;
  box-shadow: inset 0 0 0 1px var(--dgm-crash-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, dl, dd, dt, ol, ul, li, pre) { margin: 0; padding: 0; }
  & :where(ol, ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(button:disabled, button[aria-disabled="true"]) { cursor: not-allowed; }
  & :focus-visible { outline: 2px solid var(--dgm-crash-accent); outline-offset: 2px; border-radius: 5px; }
  & [hidden] { display: none !important; }
  & :where(.dgm-crash__shell, .dgm-crash__sigs ol, .dgm-crash__drawer) { scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dgm-crash-ink) 20%, transparent) transparent; }
}
.dgm-crash__shell {
  height: 100%; display: grid; gap: 12px 14px; padding: 16px 18px;
  grid-template-columns: minmax(0, 1fr) 336px;
  grid-template-rows: auto auto minmax(0, 1fr) 138px;
  grid-template-areas: "head head" "kpis kpis" "plot sigs" "hist sigs";
}
.dgm-crash__head { grid-area: head; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px 16px; min-width: 0; }
.dgm-crash__id { display: flex; align-items: center; gap: 12px; min-width: 0; flex: 1 1 340px; }
.dgm-crash__mark { display: grid; place-items: center; width: 38px; height: 38px; flex: none; border-radius: 10px; background: var(--dgm-crash-ink); color: var(--dgm-crash-bg);
  & svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
}
.dgm-crash__tt { min-width: 0; }
.dgm-crash__eye { font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--dgm-crash-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dgm-crash__tt h2 { margin-top: 3px; font-size: clamp(17px, 2cqi, 22px); font-weight: 720; letter-spacing: -.025em; line-height: 1.18; text-wrap: balance;
  & em { font-style: normal; font-family: var(--dgm-crash-mono); font-weight: 650; letter-spacing: -.04em; color: var(--dgm-crash-accent); }
  & em.ok { color: var(--dgm-crash-good); }
}
.dgm-crash__ctl { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.dgm-crash__fam { display: flex; gap: 4px;
  & button { display: inline-flex; align-items: center; gap: 6px; padding: 5px 9px; border-radius: 999px; font-size: 12px; font-weight: 600; color: var(--dgm-crash-faint); border: 1px solid var(--dgm-crash-line); transition: color .2s, background-color .2s, border-color .2s;
    & i { width: 9px; height: 9px; border-radius: 50%; border: 2px solid var(--c); transition: background-color .2s; }
    &[aria-pressed="true"] { color: var(--dgm-crash-ink); background: var(--dgm-crash-panel); border-color: color-mix(in oklch, var(--c) 40%, var(--dgm-crash-line)); }
    &[aria-pressed="true"] i { background: var(--c); }
    &:hover:not([aria-disabled="true"]) { color: var(--dgm-crash-ink); }
  }
}
.dgm-crash__seg { display: inline-flex; border-radius: 9px; border: 1px solid var(--dgm-crash-line); overflow: hidden; background: var(--dgm-crash-panel);
  & button { padding: 5px 10px; font: 600 12px var(--dgm-crash-mono); color: var(--dgm-crash-mute); transition: background-color .2s, color .2s;
    & + button { border-left: 1px solid var(--dgm-crash-line); }
    &:hover { color: var(--dgm-crash-ink); background: var(--dgm-crash-soft); }
    &[aria-checked="true"] { background: var(--dgm-crash-ink); color: var(--dgm-crash-bg); }
  }
}
.dgm-crash__chip { display: inline-flex; align-items: center; gap: 6px; padding: 5px 10px 5px 7px; border-radius: 9px; font-size: 12px; font-weight: 600; color: var(--dgm-crash-mute); border: 1px solid var(--dgm-crash-line); background: var(--dgm-crash-panel); transition: color .2s, background-color .2s, border-color .2s;
  & svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; }
  &:hover { color: var(--dgm-crash-ink); }
  &[aria-pressed="true"] { color: var(--dgm-crash-accent); border-color: color-mix(in oklch, var(--dgm-crash-accent) 40%, transparent); background: color-mix(in oklch, var(--dgm-crash-accent) 6%, var(--dgm-crash-panel)); }
}

/* KPIs */
.dgm-crash__kpis { grid-area: kpis; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 8px; }
.dgm-crash__kpi { display: grid; gap: 0; padding: 9px 12px 10px; border-radius: 11px; background: var(--dgm-crash-panel); border: 1px solid var(--dgm-crash-line); min-width: 0;
  animation: dgm-crash-in .6s var(--dgm-crash-out) both; animation-delay: calc(var(--i) * 50ms + 60ms);
