.dgm-crash__plotc, .dgm-crash__histc, .dgm-crash__sigs { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 6px; min-width: 0; min-height: 0; padding: 10px 12px; border-radius: 12px; background: var(--dgm-crash-panel); border: 1px solid var(--dgm-crash-line); }
.dgm-crash__plotc { grid-area: plot; }
.dgm-crash__histc { grid-area: hist; }
.dgm-crash__ph { display: flex; align-items: center; justify-content: space-between; gap: 6px 10px; flex-wrap: wrap; min-width: 0;
