    & span { margin-left: 6px; font-weight: 500; letter-spacing: 0; text-transform: none; color: var(--dgm-crash-faint); font-variant-numeric: tabular-nums; } }
}
.dgm-crash__sub { font-size: 11px; color: var(--dgm-crash-faint); }
.dgm-crash__quick { display: flex; flex-wrap: wrap; gap: 4px;
  & button { padding: 3px 8px; border-radius: 7px; font-size: 11.5px; font-weight: 600; color: var(--dgm-crash-mute); background: var(--dgm-crash-soft); transition: background-color .2s, color .2s;
