  & .bud { stroke: var(--dgm-crash-accent); stroke-dasharray: 4 3; }
  & .budt { font: 700 9.5px var(--dgm-crash-mono); fill: var(--dgm-crash-accent); }
  & .fps { stroke: color-mix(in oklch, var(--dgm-crash-ink) 35%, transparent); stroke-dasharray: 2 3; }
