  & .n { font: 650 12.5px var(--dgm-crash-mono); font-variant-numeric: tabular-nums; text-align: right; }
  & .m { font: 500 11px var(--dgm-crash-mono); color: var(--dgm-crash-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .dl { font: 650 10.5px var(--dgm-crash-mono); text-align: right; color: var(--dgm-crash-faint); }
  & .dl[data-s="bad"] { color: var(--dgm-crash-accent); } & .dl[data-s="good"] { color: var(--dgm-crash-good); }
