}
.dgm-crash__drawer { position: absolute; z-index: 41; top: 8px; right: 8px; bottom: 8px; width: min(420px, calc(100% - 16px)); overflow: auto; display: grid; grid-template-columns: minmax(0, 1fr); align-content: start; gap: 14px; padding: 16px 18px 18px;
