.dgm-crash__tip { position: absolute; z-index: 60; left: 0; top: 0; pointer-events: none; max-width: 250px; padding: 8px 10px; border-radius: 9px; font-size: 12px; line-height: 1.5; font-variant-numeric: tabular-nums;
