}

@keyframes dgm-crash-in { from { opacity: 0; translate: 0 5px; } }
@keyframes dgm-crash-grow { from { transform: scaleX(0); } }
@keyframes dgm-crash-pop { from { r: 0; } }

@container dgm-crash (width < 960px) {
  .dgm-crash__shell { grid-template-columns: minmax(0, 1fr) 280px; }
  .dgm-crash__kpi:nth-child(5) { display: none; }
  .dgm-crash__kpis { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@container dgm-crash (width < 760px) {
  .dgm-crash__shell { overflow: auto; padding: 14px 12px;
    grid-template-columns: minmax(0, 1fr); grid-template-rows: max-content max-content 380px 150px max-content;
