  .dgm-crash__kpi:nth-child(5) { display: grid; grid-column: span 2; }
  .dgm-crash__sigs ol { overflow: visible; }
}
@container dgm-crash (width < 460px) {
  .dgm-crash__eye { white-space: normal; }
  .dgm-crash__shell { grid-template-rows: max-content max-content 420px 150px max-content; }
  .dgm-crash__lg { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .dgm-crash {
    & .dgm-crash__kpi, & .dgm-crash__sigs li, & .dgm-crash__ram i::before { animation: none; }
