  const nextSel = (() => { const L = visible(), i = L.findIndex((x) => x.id === t.id); const n = L[i + 1] || L[i - 1]; return n ? n.id : null; })();
  if (txt) t.msgs.push(['agent', txt]);
  if (kind === 'resolve') {
    t.state = 'resolved'; t.solvedAt = deskSec(); SOLVED[SOLVED.length - 1]++; S.resolved.push(t.id);
    toast('Resolved #' + t.id + ' for ' + t.player, () => { t.state = prev.state; t.msgs = prev.msgs; SOLVED[SOLVED.length - 1]--; S.sel = t.id; refresh(true); });
  } else if (kind === 'wait') {
    t.state = 'waiting';
    toast('Replied to ' + t.player + '; SLA paused until they answer', () => { t.state = prev.state; t.msgs = prev.msgs; S.sel = t.id; refresh(true); });
  } else {
    t.state = 'escalated'; t.msgs.push(['note', 'Escalated to Tier 2 ' + (t.cat === 'billing' ? 'billing' : t.cat === 'access' ? 'account security' : t.cat === 'report' ? 'trust & safety' : 'QA') + ' by Imani.']);
    toast('Escalated #' + t.id + ' to Tier 2', () => { t.state = prev.state; t.msgs = prev.msgs; S.sel = t.id; refresh(true); });
  }
  const moved = !QBY[S.q].f(t);
  renderHead(true); drawChart(false);
  if (moved) { leave(t.id, () => { S.sel = nextSel; refresh(true); }); }
  else { refresh(true); }
}
function refresh(flip) { renderNav(); renderCats(); renderList(flip); renderPane(); renderHead(true); drawChart(false); }
