  if (S.arr >= ARRIVALS.length) return;
  const t = ARRIVALS[S.arr++]; t.born = elapsed(); all.push(t); NEW[NEW.length - 1]++;
  renderNav(); renderCats(); renderList(true); renderHead(true); drawChart(false);
