/* ---------- chart ---------- */
const svg = $('[data-chart]'), cw = $('[data-cw]'), tip = $('[data-tip]');
let CG = null;
function drawChart(anim) {
  const W = cw.clientWidth, H = cw.clientHeight; if (W < 60 || H < 40) return;
  const n = NEW.length, L = 24, R = 4, Tp = 4, B = 15, bw = (W - L - R) / n, mx = Math.ceil(Math.max(...NEW, ...SOLVED) / 5) * 5 + 5;
  const y = (v) => Tp + (H - Tp - B) - v / mx * (H - Tp - B), x = (i) => L + i * bw + bw / 2;
  let g = '';
  [0, mx / 2, mx].forEach((v) => { g += '<line class="gl" x1="' + L + '" x2="' + (W - R) + '" y1="' + y(v).toFixed(1) + '" y2="' + y(v).toFixed(1) + '"/><text class="ax" x="' + (L - 5) + '" y="' + (y(v) + 3.5).toFixed(1) + '" text-anchor="end">' + v + '</text>'; });
  g += '<g class="hv" data-hv><rect y="' + Tp + '" width="' + bw.toFixed(1) + '" height="' + (H - Tp - B) + '" rx="3"/></g>';
  NEW.forEach((v, i) => { const h = (H - Tp - B) - (y(v) - Tp); g += '<rect class="bn"' + (i === n - 1 ? ' data-now' : '') + ' style="--i:' + i + (anim && !RM.matches ? '' : ';animation:none') + '" x="' + (L + i * bw + bw * .2).toFixed(1) + '" y="' + y(v).toFixed(1) + '" width="' + (bw * .6).toFixed(1) + '" height="' + h.toFixed(1) + '" rx="2"/>'; });
  g += '<path class="ln" d="' + SOLVED.map((v, i) => (i ? 'L' : 'M') + x(i).toFixed(1) + ',' + y(v).toFixed(1)).join('') + '"/>';
  SOLVED.forEach((v, i) => { g += '<circle class="ld" cx="' + x(i).toFixed(1) + '" cy="' + y(v).toFixed(1) + '" r="2.5"/>'; });
  for (let i = 0; i < n; i += (W < 420 ? 4 : 2)) g += '<text class="ax" x="' + x(i).toFixed(1) + '" y="' + (H - 2) + '" text-anchor="middle">' + pad(i) + '</text>';
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H); svg.innerHTML = g;
  CG = { L, bw, n, W, H };
  if (S.hov >= 0) hourTip(S.hov);
}
function hourTip(i, cy) {
  if (!CG) return;
  const hv = svg.querySelector('[data-hv]'); hv.setAttribute('data-on', ''); hv.firstChild.setAttribute('x', (CG.L + i * CG.bw).toFixed(1));
  const rb = root.getBoundingClientRect(), sb = svg.getBoundingClientRect(), ax = sb.left - rb.left + CG.L + (i + .5) * CG.bw;
  const backlog = CARRY + sum(NEW.slice(0, i + 1)) - sum(SOLVED.slice(0, i + 1));
  tip.innerHTML = '<b>' + pad(i) + ':00–' + (i === CG.n - 1 ? clock(deskSec()) + ' (now)' : pad(i + 1) + ':00') + '</b>' + NEW[i] + ' new · ' + SOLVED[i] + ' solved<br>Backlog after: ' + backlog;
  tip.setAttribute('data-on', '');
  const tw = tip.offsetWidth, th = tip.offsetHeight;
  tip.style.translate = clamp(ax - tw / 2, 8, rb.width - tw - 8) + 'px ' + Math.max(8, (cy != null ? cy : sb.top - rb.top) - th - 10) + 'px';
}
function hideTip() { tip.removeAttribute('data-on'); const hv = svg.querySelector('[data-hv]'); if (hv) hv.removeAttribute('data-on'); S.hov = -1; }
svg.addEventListener('pointermove', (e) => { if (!CG) return; const b = svg.getBoundingClientRect(); const i = clamp(Math.floor((e.clientX - b.left - CG.L) / CG.bw), 0, CG.n - 1); S.hov = i; hourTip(i, e.clientY - root.getBoundingClientRect().top); });
svg.addEventListener('pointerleave', hideTip);
svg.addEventListener('keydown', (e) => {
  if (!CG) return; let i = S.hov < 0 ? CG.n - 1 : S.hov;
  if (e.key === 'ArrowRight') i = Math.min(CG.n - 1, i + 1); else if (e.key === 'ArrowLeft') i = Math.max(0, i - 1); else if (e.key === 'Escape') { hideTip(); return; } else return;
  e.preventDefault(); S.hov = i; hourTip(i);
});
svg.addEventListener('blur', hideTip);

/* ---------- events ---------- */
root.addEventListener('click', (e) => {
  const row = e.target.closest('.dgm-support__row');
  if (row && root.contains(row)) { selectRow(+row.dataset.id); return; }
  const b = e.target.closest('button'); if (!b || !root.contains(b) || b.disabled) return;
  if (b.dataset.q) { if (b.dataset.q !== S.q) { S.q = b.dataset.q; S.sel = null; renderNav(); renderCats(); renderList(false); renderPane(); } }
  else if (b.dataset.cat) { const k = b.dataset.cat; if (S.cats.has(k)) S.cats.delete(k); else S.cats.add(k); renderCats(); renderList(true); renderPane(); }
  else if (b.dataset.macro != null) {
    const t = tById(S.sel), ta = $('[data-reply]'); if (!t || !ta) return;
    const m = MACROS[+b.dataset.macro][1].replace('{p}', t.player);
    ta.value = ta.value.trim() ? ta.value.trim() + '\n\n' + m : m;
    ta.removeAttribute('aria-invalid'); $('[data-err]').hidden = true; ta.focus();
  }
  else if (b.dataset.act === 'wait' || b.dataset.act === 'esc') act(b.dataset.act);
  else if (b.hasAttribute('data-reopen')) {
    const t = tById(S.sel); if (!t) return;
    const was = t.state; t.state = 'open'; t.born = elapsed(); t.ago = Math.max(0, SLA[t.pri] - 20);
    if (was === 'resolved') SOLVED[SOLVED.length - 1]--;
    S.q = 'inbox'; S.cats.clear(); refresh(true);
    toast('Reopened #' + t.id + '; it is back in All open with 20 minutes of SLA');
  }
  else if (b.hasAttribute('data-undo')) { const u = S.undo; S.undo = null; b.hidden = true; $('[data-toast]').removeAttribute('data-on'); if (u) u(); }
  else if (b.hasAttribute('data-avail')) {
    S.avail = !S.avail; b.setAttribute('aria-checked', String(S.avail));
    $('[data-availl]').textContent = S.avail ? 'Taking tickets' : 'Away';
    $('[data-agentsub]').textContent = S.avail ? 'Tier 1 · on shift until 18:00' : 'Away · new tickets paused';
    renderHead(true); toast(S.avail ? 'You are taking tickets again' : 'Set to away; new tickets go to the team queue');
  }
});
root.addEventListener('submit', (e) => { if (e.target.closest('[data-form]')) { e.preventDefault(); act('resolve'); } });
root.addEventListener('input', (e) => { if (e.target.matches('[data-reply]') && e.target.getAttribute('aria-invalid')) { e.target.removeAttribute('aria-invalid'); $('[data-err]').hidden = true; } });
root.addEventListener('keydown', (e) => {
  const t = e.target; if (!t.closest) return;
  const row = t.closest('.dgm-support__row');
  if (row && /^(ArrowUp|ArrowDown|Home|End|Enter| )$/.test(e.key)) {
    e.preventDefault();
    const rs = $$('.dgm-support__row'), i = rs.indexOf(row);
    if (e.key === 'Enter' || e.key === ' ') { selectRow(+row.dataset.id); const ta = $('[data-reply]'); if (ta && e.key === 'Enter') ta.focus(); return; }
    const n = e.key === 'Home' ? rs[0] : e.key === 'End' ? rs[rs.length - 1] : rs[clamp(i + (e.key === 'ArrowDown' ? 1 : -1), 0, rs.length - 1)];
    if (n) selectRow(+n.dataset.id, true);
  } else if (t.closest('[data-nav]') && /^Arrow(Up|Down|Left|Right)$/.test(e.key)) {
    e.preventDefault(); const bs = $$('[data-nav] button'), i = bs.indexOf(t.closest('button')); bs[(i + (/Down|Right/.test(e.key) ? 1 : bs.length - 1)) % bs.length].focus();
  } else if (t.matches('[data-reply]') && e.key === 'Enter' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); act('resolve'); }
  else if (e.key === 'Escape' && $('[data-toast]').hasAttribute('data-on')) { $('[data-toast]').removeAttribute('data-on'); }
