/* ---------- live tick: SLA rings, countdowns, arrivals ---------- */
function tick() {
  if (!root.isConnected) return;
  setTimeout(tick, 1000);
  if (document.hidden || !S.vis) return;
  let reorder = false;
  $$('.dgm-support__row').forEach((r) => {
    const t = tById(+r.dataset.id); if (!t || t.state !== 'open') return;
    const st = stOf(t); if (r.dataset.st !== st) { r.dataset.st = st; reorder = true; }
    const rem = r.querySelector('[data-rem]'), f = fRem(t); if (rem.textContent !== f) rem.textContent = f;
    if (!RM.matches || Math.floor(elapsed()) % 10 === 0) r.firstChild.style.setProperty('--dgm-support-sla', clamp(remain(t) / (SLA[t.pri] * 60), 0, 1).toFixed(4));
  });
  const ps = $('[data-psla]'), cur = tById(S.sel); if (ps && cur) { const l = slaLine(cur); if (ps.textContent !== l) ps.textContent = l; }
  renderHead(false);
  if (reorder) { renderNav(); }
  const el = elapsed();
  if (S.avail && el - S.lastArr > 34 && S.arr < ARRIVALS.length) { S.lastArr = el; arrive(); }
}
const io = new IntersectionObserver((en) => { S.vis = en[0].isIntersecting; });
let rt = 0, ck = '';
const ro = new ResizeObserver(() => {
  cancelAnimationFrame(rt);
  rt = requestAnimationFrame(() => {
    if (!root.isConnected) { ro.disconnect(); io.disconnect(); return; }
    const k = cw.clientWidth + 'x' + cw.clientHeight; if (k !== ck) { const first = !ck; ck = k; drawChart(first); }
  });
});
$('[data-carry]').textContent = '\u00b7 ' + CARRY + ' carried over';
renderNav(); renderCats(); renderList(false); renderPane(); renderHead(true);
ro.observe(cw); io.observe(root);
setTimeout(tick, 1000);
